using System;using System.IO;using System.IO.Compression;using System.Text;using System.Linq;using System.Collections;using System.Collections.Generic;using System.Reflection;using System.Diagnostics;using System.Threading;using System.Web.Script.Serialization;
namespace PZ3D {
 static class JavaComponentsTests {
  static int checks;static readonly JavaScriptSerializer Json=new JavaScriptSerializer();
  static void Check(bool value,string label){if(!value)throw new Exception("FAIL: "+label);checks++;Console.WriteLine("PASS: "+label);}
  static void Put(string path,string text){Directory.CreateDirectory(Path.GetDirectoryName(path));File.WriteAllText(path,text,new UTF8Encoding(false));}
  static Dictionary<string,object> Map(object value){return Json.Deserialize<Dictionary<string,object>>(Json.Serialize(value));}
  static Dictionary<string,object>[] Rows(Dictionary<string,object> value){return ((IEnumerable)value["rows"]).Cast<Dictionary<string,object>>().ToArray();}
  static string S(Dictionary<string,object> d,string key){return Convert.ToString(d[key]);}
  static bool B(Dictionary<string,object> d,string key){return Convert.ToBoolean(d[key]);}
  static object Call(object service,string method,params object[] args){try{return service.GetType().GetMethod(method,BindingFlags.Instance|BindingFlags.Public|BindingFlags.NonPublic).Invoke(service,args);}catch(TargetInvocationException ex){throw ex.InnerException;}}
  sealed class Fixture {
   internal readonly string Root,Home;internal readonly Engine E;
   internal Fixture(string existing=null){Root=existing??Path.Combine(Path.GetTempPath(),"ozl-jc-"+Guid.NewGuid().ToString("N").Substring(0,8));Home=Path.Combine(Root,"home");E=new Engine(Path.Combine(Root,"steam","steamapps","common","PZ"),Path.Combine(Root,"user"),Path.Combine(Root,"data"),true);if(existing!=null)return;Put(E.Config,Json.Serialize(new{vmArgs=new[]{"-agentlib:zbNative","-Duser.home="+Home}}));Put(Path.Combine(E.Game,"version.txt"),"42.21");Put(Path.Combine(E.Game,"ProjectZomboid64.exe"),"fixture");Put(Path.Combine(E.Game,"ZombieBuddy.jar"),"fixture");Put(Path.Combine(E.Game,"zbNative.dll"),"fixture");Put(E.Mods,"VERSION = 1,\nmods\n{\n    mod = ZombieBuddy,\n    mod = Other,\n}\nmaps\n{\n    map = KeepMap,\n}\ncustom = keep\n");}
   internal object Open(Action<int,string> progress=null,Func<SteamLaunchOptionsSnapshot> options=null){var type=typeof(Engine).Assembly.GetType("PZ3D.JavaComponents");Check(type!=null,"native Java manager exists");var engine=options==null?E:new Engine(E.Game,E.User,E.Data,true,options);return Activator.CreateInstance(type,BindingFlags.Instance|BindingFlags.Public|BindingFlags.NonPublic,null,progress==null?new object[]{engine}:new object[]{engine,progress},null);}
   internal string Add(string id="External",string package="sample.external",string item=null,string commonJar="common.jar",string activeJar="active.jar"){
    string root=item==null?Path.Combine(E.User,"mods",id):Path.Combine(E.Workshop,item,"mods",id);Put(Path.Combine(root,"common","mod.info"),"id="+id+"\nname=External Java\njavaJarFile=media/java/client/"+commonJar+"\njavaPkgName="+package+"\n");Put(Path.Combine(root,"42","mod.info"),"id="+id+"\nname=External active\njavaJarFile=media/java/client/"+activeJar+"\njavaPkgName="+package+"\nrequire=\\ZombieBuddy\n");Jar(Path.Combine(root,"common","media","java","client",commonJar),package);Jar(Path.Combine(root,"42","media","java","client",activeJar),package);return root;
   }
   internal string Config{get{return Path.Combine(Home,".zombie_buddy","config.json");}}
   internal void Enabled(string id){Put(E.Mods,File.ReadAllText(E.Mods).Replace("    mod = Other,","    mod = Other,\n    mod = "+id+","));}
   internal void Preload(string id,string root){Put(Config,Json.Serialize(new{trusted_authors=new object[0],custom=new{keep=17},preload_mods=new Dictionary<string,object>{{id,new{infPath=Path.Combine(root,"42","mod.info"),jarPath=Path.Combine(root,"42","media","java","client","active.jar")}}, {"Keep",new{infPath="unchanged-info",jarPath="unchanged.jar"}}}}));}
   internal Dictionary<string,object> List(object service){return Map(Call(service,"List"));}
   internal Dictionary<string,object> Row(object service,string id){return Rows(List(service)).Single(row=>S(row,"modId")==id);}
   internal Dictionary<string,object> Preview(object service,string id,string operation,string receipt=null){var list=List(service);var row=Rows(list).Single(r=>S(r,"modId")==id);return Map(Call(service,"Preview",S(row,"token"),operation,S(list,"stamp"),receipt));}
   internal Dictionary<string,object> Apply(object service,Dictionary<string,object> preview,bool yes=true,CancellationToken cancel=default(CancellationToken)){return Map(Call(service,"Apply",S(preview,"previewStamp"),yes,cancel));}
  }
  static void Jar(string path,string package){Directory.CreateDirectory(Path.GetDirectoryName(path));if(File.Exists(path))File.Delete(path);using(var zip=ZipFile.Open(path,ZipArchiveMode.Create)){using(var output=new StreamWriter(zip.CreateEntry("META-INF/MANIFEST.MF").Open()))output.Write("Manifest-Version: 1.0\r\n\r\n");using(var output=new StreamWriter(zip.CreateEntry(package.Replace('.','/')+"/Main.class").Open()))output.Write("fixture class bytes, never executed");}}
  static bool HasMod(Fixture f,string id){return SaveProfiles.DefaultMods(SaveProfiles.DefaultBytes(f.E)).Any(v=>v.TrimStart('\\')==id);}
  static void Inventory(){var f=new Fixture();string root=f.Add();f.Add("Collision","sample.external");f.Add("Viewpoint","viewpoint","3809306528");Put(Path.Combine(f.E.Game,"jre64","lib","java-runtime.jar"),"game runtime");Put(f.E.Config,Json.Serialize(new{vmArgs=new[]{"-agentlib:zbNative","-Duser.home="+f.Home,"-javaagent:custom-agent.jar=password=fixture"}}));var service=f.Open();var rows=Rows(f.List(service));var row=rows.Single(r=>S(r,"modId")=="External");Check(S(row,"packageName")=="sample.external"&&S(row,"name")=="External active"&&S(row,"sourceKind")=="user","generic manual metadata uses active-version declaration first");Check(((IEnumerable)row["conflicts"]).Cast<object>().Any(),"same declared package is reported as a conflict");Check(rows.Any(r=>S(r,"managedKey")=="viewpoint"),"existing component remains routed to its managed key");Check(rows.Any(r=>S(r,"sourceKind")=="startupAgent"&&!B(r,"canUninstall")),"unknown startup agent is visible and read only");Check(!Json.Serialize(rows).Contains("password=fixture")&&!Json.Serialize(rows).Contains("java-runtime.jar"),"inventory excludes agent options and game runtime dependencies");Check(!Directory.Exists(f.E.Data),"listing has no backup or state writes");((IDisposable)service).Dispose();}
  static void ToggleAndRestore(){var f=new Fixture();string root=f.Add();f.Enabled("External");f.Preload("External",root);var service=f.Open();var preview=f.Preview(service,"External","disable");Check(B(preview,"supported"),"standard external component offers explicit disable preview");byte[] before=File.ReadAllBytes(f.E.Mods);Check(!B(f.Apply(service,preview,false),"changed")&&before.SequenceEqual(File.ReadAllBytes(f.E.Mods)),"declined operation leaves files unchanged");var result=f.Apply(service,preview);Check(S(result,"status")=="completed"&&HasMod(f,"External")&&before.SequenceEqual(File.ReadAllBytes(f.E.Mods)),"disable preserves the selected default row for bundled Lua");var config=Json.Deserialize<Dictionary<string,object>>(File.ReadAllText(f.Config));var preload=(Dictionary<string,object>)config["preload_mods"];Check(!preload.ContainsKey("External")&&preload.ContainsKey("Keep")&&((Dictionary<string,object>)config["custom"])["keep"].ToString()=="17","disable removes selected preload and preserves unrelated fields");Check(File.Exists(Path.Combine(root,"42","media","java","client","active.jar"))&&File.ReadAllText(f.E.Mods).Contains("map = KeepMap")&&File.ReadAllText(f.E.Mods).Contains("custom = keep"),"disable preserves payloads, map block, and custom text");config["laterEdit"]=true;Put(f.Config,Json.Serialize(config));Put(f.E.Mods,File.ReadAllText(f.E.Mods).Replace("    mod = Other,","    mod = Later,\n    mod = Other,"));var restore=f.Preview(service,"External","restore",S(result,"receiptId"));Check(B(restore,"supported"),"owned disable receipt offers restoration after unrelated edits");result=f.Apply(service,restore);config=Json.Deserialize<Dictionary<string,object>>(File.ReadAllText(f.Config));Check(S(result,"status")=="completed"&&HasMod(f,"External")&&HasMod(f,"Later")&&config.ContainsKey("laterEdit")&&((Dictionary<string,object>)config["preload_mods"]).ContainsKey("External"),"restore merges only selected row and preload without reverting later edits");((IDisposable)service).Dispose();}
  static void Uninstall(){var f=new Fixture();string root=f.Add();f.Enabled("External");f.Preload("External",root);string active=Path.Combine(root,"42","media","java","client","active.jar"),common=Path.Combine(root,"common","media","java","client","common.jar");byte[] original=File.ReadAllBytes(active);Put(active+".zbs","signature fixture");Put(Path.Combine(root,"42","media","lua","client","keep.lua"),"keep");var service=f.Open();var preview=f.Preview(service,"External","uninstall");Check(B(preview,"supported"),"unique declared external payload offers uninstall");var result=f.Apply(service,preview);Check(S(result,"status")=="completed"&&!File.Exists(active)&&!File.Exists(common)&&!File.Exists(active+".zbs"),"uninstall quarantines active and common fallback JARs and signature");Check(File.Exists(Path.Combine(root,"42","mod.info"))&&File.Exists(Path.Combine(root,"42","media","lua","client","keep.lua")),"uninstall retains the bundle metadata and non-Java content");var restore=f.Preview(service,"External","restore",S(result,"receiptId"));Put(active,"foreign update");Check(S(f.Apply(service,restore),"status")!="completed"&&File.ReadAllText(active)=="foreign update","stale restore never overwrites a newly installed payload");File.Delete(active);restore=f.Preview(service,"External","restore",S(result,"receiptId"));result=f.Apply(service,restore);Check(S(result,"status")=="completed"&&original.SequenceEqual(File.ReadAllBytes(active))&&File.Exists(common)&&File.ReadAllText(active+".zbs")=="signature fixture","explicit restore restores exact owned payloads and sidecar");((IDisposable)service).Dispose();}
  static void Boundaries(){var f=new Fixture();string root=f.Add();f.Add("Viewpoint","viewpoint","3809306528");var service=f.Open();Check(!B(f.Preview(service,"Viewpoint","uninstall"),"supported"),"generic manager refuses to replace existing managed-component lifecycle");Put(Path.Combine(root,"42","mod.info"),File.ReadAllText(Path.Combine(root,"42","mod.info")).Replace("require=\\ZombieBuddy","require=MissingDependency"));Check(!B(f.Preview(service,"External","enable"),"supported"),"enabling does not silently install or ignore missing dependencies");Put(Path.Combine(root,"42","mod.info"),"id=External\njavaJarFile=../../../../outside.jar\njavaPkgName=sample.external\n");var row=f.Row(service,"External");Check(!B(row,"canUninstall"),"escaped payload path is read only");f.Add("Healthy","sample.healthy");Check(B(f.Row(service,"Healthy"),"canUninstall"),"invalid metadata does not block independent healthy rows");var preview=f.Preview(service,"Healthy","uninstall");File.AppendAllText(Path.Combine(f.E.User,"mods","Healthy","42","mod.info"),"\nname=changed\n");Check(S(f.Apply(service,preview),"status")!="completed"&&File.Exists(Path.Combine(f.E.User,"mods","Healthy","42","media","java","client","active.jar")),"changed selected metadata invalidates preview before writes");((IDisposable)service).Dispose();}
  static void DownloadAndUnknown(){var f=new Fixture();f.Add("One","sample.one","999001");f.Add("Two","sample.two","999001");var service=f.Open();var rows=Rows(Map(Call(service,"InspectDownloaded",999001UL)));Check(rows.Count(r=>S(r,"workshopId")=="999001")==2&&!HasMod(f,"One")&&!HasMod(f,"Two"),"downloaded item inspection lists each submod without enabling the bundle");f.Enabled("One");Put(f.E.Config,Json.Serialize(new{vmArgs=new[]{"-agentlib:zbNative=config_dir=relative-config"}}));var row=f.Row(service,"One");Check(S(row,"preloadState")=="unknown"&&!B(f.Preview(service,"One","disable"),"supported"),"unverified preload directory cannot produce a false fully-disabled result");((IDisposable)service).Dispose();}
  static void Cancellation(){var f=new Fixture();string root=f.Add();f.Enabled("External");var cancel=new CancellationTokenSource();var service=f.Open((v,t)=>{if(v>0)cancel.Cancel();});var preview=f.Preview(service,"External","uninstall");var result=f.Apply(service,preview,true,cancel.Token);Check(S(result,"status")=="cancelled"&&!B(result,"recoveryPending")&&HasMod(f,"External")&&File.Exists(Path.Combine(root,"42","media","java","client","active.jar")),"cancellation after a committed file safely restores exact changes");((IDisposable)service).Dispose();}
  static void SourceIdentity(){var f=new Fixture();string root=f.Add();f.Enabled("External");var service=f.Open();var preview=f.Preview(service,"External","disable");string jar=Path.Combine(root,"42","media","java","client","active.jar");DateTime time=File.GetLastWriteTimeUtc(jar);byte[] bytes=File.ReadAllBytes(jar);bytes[bytes.Length-8]^=1;File.WriteAllBytes(jar,bytes);File.SetLastWriteTimeUtc(jar,time);Check(S(f.Apply(service,preview),"status")!="completed"&&HasMod(f,"External"),"selected JAR change is rejected even with identical size and timestamp");((IDisposable)service).Dispose();}
