  static void SourceConfigBoundaries(){var f=new Fixture();f.Add();f.Enabled("External");string steam=Path.Combine(f.Root,"steam"),vdf=Path.Combine(steam,"userdata","44","config","localconfig.vdf");Put(vdf,"\"UserLocalConfigStore\" { \"Software\" { \"Valve\" { \"Steam\" { \"apps\" { \"108600\" { \"LaunchOptions\" \"-Duser.home=other-home\" } } } } } }");var service=f.Open(null,()=>SteamLaunchOptions.Read(steam,44));Check(S(f.Row(service,"External"),"preloadState")=="unknown"&&!B(f.Preview(service,"External","disable"),"supported"),"Steam user-home override cannot authorize writes to the guessed Buddy config");((IDisposable)service).Dispose();service=f.Open(null,()=>new SteamLaunchOptionsSnapshot(null,0,null,SteamLaunchOptionsState.UnknownIdentity));Check(!B(f.Preview(service,"External","disable"),"supported"),"unknown Steam identity leaves preload-source dependent operations unavailable");((IDisposable)service).Dispose();service=f.Open();foreach(string[] args in new[]{new[]{"-agentlib:zbNativeEvil","-Duser.home="+f.Home},new[]{"-agentlib:zbNative","-Duser.home="+f.Home,"-Dzb.config_dir="+Path.Combine(f.Root,"other")},new[]{"-agentlib:custom","-Duser.home="+f.Home},new[]{"-javaagent:"+Path.Combine(f.Root,"foreign","ZombieBuddy.jar"),"-Duser.home="+f.Home},new[]{"-agentpath:"+Path.Combine(f.Root,"foreign","zbNative.dll"),"-Duser.home="+f.Home}}){Put(f.E.Config,Json.Serialize(new{vmArgs=args}));Check(!B(f.Preview(service,"External","disable"),"supported"),"ambiguous Buddy prefix or configuration system property is refused");}((IDisposable)service).Dispose();}
